    12→const ConfigTab = () => {
    13→  const qc = useQueryClient();
    14→  const [saving, setSaving] = useState(false);
    15→
    16→  const { data: config } = useQuery({
    17→    queryKey: ["admin_config"],
    18→    queryFn: async () => {
    19→      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
    20→      if (error) throw error;
    21→      return data;
    22→    },
    23→  });
    24→
    25→  const [form, setForm] = useState({ max_resumes_per_job: 10, max_file_size_mb: 5, resume_retention_days: 30, payg_per_resume_cost: 0.07 });
    26→  const [loaded, setLoaded] = useState(false);
    27→
    28→  if (config && !loaded) {
    29→    setForm({
    30→      max_resumes_per_job: config.max_resumes_per_job,
    31→      max_file_size_mb: config.max_file_size_mb,
    32→      resume_retention_days: config.resume_retention_days,
    33→      payg_per_resume_cost: (config as any).payg_per_resume_cost ?? 0.07,
    34→    });
    35→    setLoaded(true);
    36→  }
    37→
    38→  const validate = () => {
    39→    if (form.max_resumes_per_job < 1 || form.max_resumes_per_job > 20) { toast.error("Max resumes per job must be 1–20"); return false; }
    40→    if (form.max_file_size_mb < 1 || form.max_file_size_mb > 50) { toast.error("Max file size must be 1–50 MB"); return false; }
    41→    if (form.resume_retention_days < 1) { toast.error("Retention days must be at least 1"); return false; }
    42→    if (form.payg_per_resume_cost < 0) { toast.error("PAYG cost cannot be negative"); return false; }
    43→    return true;
    44→  };
    45→
    46→  const save = async () => {
    47→    if (!validate()) return;
    48→    setSaving(true);
    49→    try {
    50→      const payload = { ...form, max_resumes_per_job: Math.min(form.max_resumes_per_job, 20) } as any;
    51→      const { error } = await supabase.from("platform_config").update(payload).eq("id", config?.id);
    52→      if (error) { toast.error(error.message); return; }
    53→      toast.success("Config updated");
    54→      logAuditAction("config.update", "platform_config", config?.id, form);
    55→      qc.invalidateQueries({ queryKey: ["admin_config"] });
    56→      qc.invalidateQueries({ queryKey: ["platform_config"] });
    57→    } finally {
    58→      setSaving(false);
    59→    }
    60→  };
    61→
    62→  return (
    63→    <Card>
    64→      <CardHeader className="pb-3"><CardTitle className="text-lg">Platform Configuration</CardTitle></CardHeader>
    65→      <CardContent className="space-y-4">
    66→        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
    67→          <div>
    68→            <Label>Max Resumes/Job (1–20)</Label>
    69→            <Input type="number" min={1} max={20} value={form.max_resumes_per_job} onChange={(e) => setForm({ ...form, max_resumes_per_job: parseInt(e.target.value) || 0 })} />
    70→          </div>
    71→          <div>
    72→            <Label>Max File Size (MB)</Label>
    73→            <Input type="number" min={1} max={50} value={form.max_file_size_mb} onChange={(e) => setForm({ ...form, max_file_size_mb: parseInt(e.target.value) || 0 })} />
    74→          </div>
    75→          <div>
    76→            <Label>Retention Days</Label>
    77→            <Input type="number" min={1} value={form.resume_retention_days} onChange={(e) => setForm({ ...form, resume_retention_days: parseInt(e.target.value) || 0 })} />
    78→          </div>
    79→          <div>
    80→            <Label>PAYG Per Resume Cost ($)</Label>
    81→            <Input type="number" step="0.01" min={0} value={form.payg_per_resume_cost} onChange={(e) => setForm({ ...form, payg_per_resume_cost: parseFloat(e.target.value) || 0 })} />
    82→          </div>
    83→        </div>
    84→        <Button onClick={save} disabled={saving}>
    85→          {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
    86→          Save Configuration
    87→        </Button>
    88→      </CardContent>
    89→    </Card>
    90→  );
    91→};
    92→
    93→export default ConfigTab;
